const WIDTHS = [640, 960, 1280, 1672] as const;

/**
 * Product diagram with AVIF/WebP responsive variants (generated by scripts/optimise-images.py) and the
 * original PNG as the universal fallback. Intrinsic dimensions are declared, so layout is stable.
 * `base` is the path of the PNG without the extension, e.g. "/media/ai-governance/nova-ai-...-workflow".
 */
export function ResponsiveDiagram({
  base,
  alt,
  title,
  sizes = "(min-width: 1024px) 560px, 100vw",
  className,
  width = 1672,
  height = 941,
}: {
  base: string;
  alt: string;
  title?: string;
  sizes?: string;
  className?: string;
  width?: number;
  height?: number;
}) {
  const srcSet = (extension: "avif" | "webp") =>
    WIDTHS.map((w) => `${base}-${w}.${extension} ${w}w`).join(", ");
  return (
    <picture>
      <source type="image/avif" srcSet={srcSet("avif")} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet("webp")} sizes={sizes} />
      <img
        src={`${base}.png`}
        alt={alt}
        {...(title ? { title } : {})}
        width={width}
        height={height}
        loading="lazy"
        decoding="async"
        className={className}
      />
    </picture>
  );
}
